export function add(a: number, b: number): number {
  return a + b;
}

export function clamp(n: number, min: number, max: number): number {
  if (min > max) throw new RangeError(`clamp: min ${min} is greater than max ${max}`);
  if (n < min) return min;
  if (n > max) return max;
  return n;
}

expected_files.test/clamp.test.ts:
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/math.ts";

test("clamp limits to the range", () => {
  assert.equal(clamp(5, 0, 3), 3);
  assert.equal(clamp(-1, 0, 3), 0);
  assert.equal(clamp(2, 0, 3), 2);
});

test("clamp rejects an inverted range", () => {
  assert.throws(() => clamp(1, 3, 0), RangeError);
});

